figures.script:
diagram("mode: sequence
[Call stack] as s
[Web APIs] as w
[Task queue] as q
s -> w : setTimeout(cb, 0)
s -> s : run remaining code
w -> q : timer done, enqueue cb
q -> s : stack empty, push cb
s -> s : run cb
@0 s -> w : setTimeout(cb, 0)
@1 s -> s : run remaining code
@2 w -> q : timer done, enqueue cb
@3 q -> s : stack empty, push cb
@4 s -> s : run cb");

diagram("mode: sequence
[User] as u
[Browser JS] as j
[Server] as s
u -> j : click Load
j -> s : fetch /api/items
s --> j : 200 JSON
j -> j : update DOM
j --> u : list appears
@0 u -> j : click Load
@1 j -> s : fetch /api/items
@2 s -> j : 200 JSON
@3 j -> j : update DOM
@4 j -> u : list appears");
